const skills=[
{id:'youtube-manager',name:'YouTube Manager',group:'Start here',desc:'Sets up and maintains channel memory, approved strategy, and durable creator context.',when:'You are setting up the system or making a channel-wide decision.',does:'Creates a durable source of truth for audience, positioning, format, brand rules, and confirmed preferences.',inputs:'Channel URL or handle, recent uploads, optional Studio evidence, and creator decisions.',outputs:'An approved CHANNEL_MEMORY.md and focused strategy guidance.',approval:'A proposed channel profile is shown before persistent memory is created or replaced.',steps:['Load the relevant approved channel context.','Research the channel, recent uploads, and representative public evidence.','Present an evidence-based profile for the creator to approve.','Maintain confirmed memory as durable decisions change.'],related:['topic-scout','creator-voice']},
{id:'topic-scout',name:'Topic Scout',group:'The main flow',desc:'Researches and ranks video opportunities using current audience, search, and competition evidence.',when:'You need a defensible idea shortlist before writing a video.',does:'Turns a broad topic space into specific, channel-fit video opportunities with clear trade-offs.',inputs:'CHANNEL_MEMORY.md, recent uploads, relevant performance reviews, and a research brief.',outputs:'Up to five prioritized idea briefs and one recommended direction.',approval:'The creator selects an idea before a video project or script is created.',steps:['Load the channel context and recent channel state.','Research current viewer need, search, recommendation, and competition signals.','Develop specific ideas with audience, promise, and credible proof.','Rank ideas with explicit evidence, confidence, and trade-offs.'],related:['youtube-manager','video-kit']},
{id:'review-grill',name:'Review Grill',group:'The main flow',desc:'Researches a product and captures the creator’s first-hand experience one question at a time.',when:'You are building a hands-on review and need experience worth trusting.',does:'Separates current checkable facts from the creator’s real use, observations, limitations, and verdict.',inputs:'Product or service identity, creator answers, channel context, and public source material.',outputs:'A structured review-brief.md ready for Video Kit.',approval:'For a substantial interview, the experience brief is summarized for corrections before saving.',steps:['Load channel context and research the exact product first.','Ask one adaptive question at a time about first-hand use.','Keep observed experience, research, estimates, and unknowns distinct.','Save a structured experience brief only when the creator asks or agrees.'],related:['video-kit','creator-voice']},
{id:'video-kit',name:'Video Kit',group:'The main flow',desc:'Develops a selected topic into a researched outline, script, publishing package, or production brief.',when:'The topic is chosen and you need the actual long-form video package.',does:'Combines approved channel context, research, and creator evidence into the exact video artifacts requested.',inputs:'CHANNEL_MEMORY.md, CREATOR_VOICE.md, selected topic, research, review brief, and format constraints.',outputs:'An outline or script, publishing assets, and optional production guidance in the video project.',approval:'It produces only the requested deliverable; hooks and packaging stay open until the creator locks them.',steps:['Load approved channel and creator voice context.','Find or create the matching video project without duplicating work.','Use a review brief for firsthand review claims.','Research the selected topic and produce only the requested video assets.'],related:['topic-scout','review-grill','youtube-thumbnail','youtube-shorts']},
{id:'youtube-thumbnail',name:'YouTube Thumbnail',group:'Packaging & distribution',desc:'Plans and produces an accurate visual promise for a YouTube video.',when:'You need a thumbnail concept, mockup, or finished export.',does:'Pairs the title with one clear visual hook, using authentic visuals and channel-aware typography.',inputs:'Video project, working title, script or review brief, brand kit, and source photos or footage.',outputs:'A thumbnail brief, approved mockup, editable composition, and 1280×720 final export.',approval:'The creator approves a concept and a static mockup before source photos are edited or a final thumbnail is exported.',steps:['Load project context and lock the honest packaging promise.','Inspect authentic visual assets for focal subject and text space.','Present two or three thumbnail briefs.','Create a static mockup, then produce only after approval.'],related:['video-kit','youtube-analytics']},
{id:'youtube-shorts',name:'YouTube Shorts',group:'Packaging & distribution',desc:'Plans and produces channel-aware Shorts from an idea, long-form video, review brief, or footage.',when:'You need a Short concept, script, overlay plan, production brief, or approved render.',does:'Chooses the right Short format and moves through a controlled production path without losing the parent video’s promise.',inputs:'Channel context, video project, source footage, script, review brief, and requested delivery level.',outputs:'A Shorts brief, script, optional overlay plan, production files, and rendered Short when authorized.',approval:'Scene plan comes before mockups, mockups before animation, and output review before changing a final export.',steps:['Load channel and video-project context.','Resolve only gaps that materially affect the chosen Short outcome.','Choose the delivery level: concept, brief, overlay prototype, or render.','Save the work with the parent video and verify finished assets.'],related:['social-repurpose','video-kit','youtube-thumbnail']},
{id:'social-repurpose',name:'Social Repurpose',group:'Packaging & distribution',desc:'Finds distinct cross-platform value in an approved YouTube video or review source.',when:'You want a focused distribution plan beyond the long-form video.',does:'Maps the strongest moments to selected formats without mechanically rewording or resizing the original.',inputs:'Approved source video or review brief, project assets, channel context, brand kit, and voice profile.',outputs:'A repurpose-plan.md and selected derivative assets routed to the right specialist.',approval:'The creator selects the proposed derivatives before any asset, edit, graphic, or prompt is produced.',steps:['Load source and approved channel context.','Identify self-contained angles with a clear platform-specific promise.','Present a small repurpose plan with effort and link-back strategy.','Route chosen work to Shorts, Thumbnail, or Video Kit.'],related:['youtube-shorts','youtube-thumbnail','video-kit']},
{id:'creator-voice',name:'Creator Voice',group:'Start here',desc:'Builds an approved voice profile from real creator transcripts, scripts, descriptions, and writing samples.',when:'You want scripts and channel copy to consistently sound like the creator.',does:'Captures real speaking and writing patterns without inventing a personality or flattening natural code-switching.',inputs:'CHANNEL_MEMORY.md, brand kit, existing voice profile, and representative samples.',outputs:'A concise, creator-approved CREATOR_VOICE.md.',approval:'The creator reviews the profile and evidence behind its meaningful rules before it is saved.',steps:['Load existing channel context and approved profile.','Collect only enough representative spoken and written evidence.','Analyze observable patterns and separate rules from tentative observations.','Present the profile for corrections, then save after approval.'],related:['youtube-manager','video-kit','review-grill']},
{id:'youtube-analytics',name:'YouTube Analytics',group:'Learning',desc:'Turns supplied YouTube Studio evidence into a small set of evidence-based next decisions.',when:'You want to understand packaging, retention, traffic, formats, or audience signals.',does:'Reads the viewer journey without inventing private data or mistaking a single pattern for causation.',inputs:'Studio screenshots, exports or reports, CHANNEL_MEMORY.md, a defined comparison scope, and dated prior reviews.',outputs:'Three to five grounded findings and no more than three next actions.',approval:'Potential durable learnings are proposed for channel memory and only saved after creator confirmation.',steps:['Set the question, time window, formats, and comparison scope.','Normalize comparisons so similar videos and lifecycle windows are compared.','Separate observed facts, plausible interpretations, and unknowns.','Give a small decision set with evidence and future signals to review.'],related:['topic-scout','youtube-thumbnail','video-kit']}
];
const groups=[['Start here','Set the system up once, then give every project context.'],['The main flow','The idea-to-video backbone, in the order most creators reach for it.'],['Packaging & distribution','Turn an approved video into a truthful reason to click and share.'],['Learning','Read the evidence and choose the next useful improvement.']];
const byId=Object.fromEntries(skills.map(s=>[s.id,s]));
const esc=v=>v.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const related=ids=>ids.map(i=>`<a href="skill.html?skill=${i}">${byId[i].name}</a>`).join(' · ');
function renderHome(){const flow=document.querySelector('#flow-list');if(!flow)return;const main=['topic-scout','review-grill','video-kit','youtube-thumbnail','youtube-shorts','youtube-analytics'];flow.innerHTML=main.map((id,i)=>{const s=byId[id];return `<a class="flow-row" href="skill.html?skill=${id}"><span class="flow-number">0${i+1}</span><h3>${s.name}</h3><p>${s.desc}</p><span class="flow-arrow">→</span></a>`}).join('');document.querySelector('#skill-groups').innerHTML=groups.map(([g,sub])=>`<section class="skill-group"><div class="group-title"><h3>${g}</h3><p>${sub}</p></div><div class="skill-list">${skills.filter(s=>s.group===g).map((s,i)=>`<a class="skill-item" href="skill.html?skill=${s.id}"><span class="skill-id">${String(i+1).padStart(2,'0')}</span><h4>${s.name}</h4><p>${s.desc}</p><span class="arrow">→</span></a>`).join('')}</div></section>`).join('')}
function renderSidebar(current){return `<p class="sidebar-heading">Creator Skills</p>${groups.map(([g])=>`<div class="side-group"><h3>${g}</h3>${skills.filter(s=>s.group===g).map(s=>`<a class="${s.id===current?'active':''}" href="skill.html?skill=${s.id}">${s.name}</a>`).join('')}</div>`).join('')}`}
async function renderSkill(){const root=document.querySelector('#docs-main');if(!root)return;const id=new URLSearchParams(location.search).get('skill')||'youtube-manager',s=byId[id];document.querySelector('#docs-sidebar').innerHTML=renderSidebar(id);if(!s){root.innerHTML='<div class="not-found"><p class="kicker">Not found</p><h1>That skill does not exist.</h1><p><a href="index.html">Return to Creator Skills</a></p></div>';return}document.title=`${s.name} — Creator Skills`;const source=await fetch(`skill-source/${s.id}.md`).then(r=>r.ok?r.text():'Source file unavailable.');root.innerHTML=`<div class="breadcrumb"><a href="index.html">Creator Skills</a> / ${s.group} / ${s.name}</div><header class="skill-page-header"><p class="kicker">${s.group}</p><h1>${s.name}</h1><p>${s.desc}</p><div class="meta-grid"><div class="meta-card"><span>Use when</span><strong>${s.when}</strong></div><div class="meta-card"><span>Produces</span><strong>${s.outputs}</strong></div><div class="meta-card"><span>Related</span><strong>${related(s.related)}</strong></div></div></header><section class="doc-section" id="overview"><h2>What it does</h2><p>${s.does}</p></section><section class="doc-section" id="workflow"><h2>Workflow</h2><ol class="workflow-steps">${s.steps.map(x=>`<li>${x}</li>`).join('')}</ol></section><section class="doc-section" id="inputs"><h2>Inputs & outputs</h2><div class="detail-grid"><div class="detail-card"><h3>What you provide</h3><p>${s.inputs}</p></div><div class="detail-card"><h3>What you get</h3><p>${s.outputs}</p></div></div></section><section class="doc-section" id="approval"><h2>Creator approval</h2><div class="approval-box">${s.approval}</div></section><section class="doc-section" id="source"><h2>Source instructions</h2><p>This is the current underlying <code>SKILL.md</code> file, included so the workflow remains inspectable and editable.</p><button class="source-toggle" id="toggle-source">Show SKILL.md</button><pre class="raw-source" id="raw-source" hidden>${esc(source)}</pre></section>`;document.querySelector('#toggle-source').onclick=e=>{const pre=document.querySelector('#raw-source'),open=pre.hidden;pre.hidden=!open;e.target.textContent=open?'Hide SKILL.md':'Show SKILL.md'};document.querySelector('#on-page').innerHTML='<p>On this page</p><a href="#overview">What it does</a><a href="#workflow">Workflow</a><a href="#inputs">Inputs & outputs</a><a href="#approval">Creator approval</a><a href="#source">Source instructions</a>'}
renderHome();renderSkill();
